WITH scored AS (SELECT *, ROW_NUMBER() OVER w_part AS row_seq, CUME_DIST() OVER (PARTITION BY dept_id, manager_id ORDER BY salary DESC) AS salary_cume_dist, LAG(salary, 2) OVER w_running AS prev_salary, AVG(salary) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS salary_avg_5_prior FROM employees WINDOW w_part AS (PARTITION BY level ORDER BY salary DESC, id), w_running AS (PARTITION BY manager_id, dept_id ORDER BY salary, id)) SELECT level, COUNT(DISTINCT level) AS distinct_levels, PERCENTILE_APPROX(row_seq, ARRAY(0.25, 0.5, 0.75)) AS row_seq_quartiles, SIZE(COLLECT_SET(job_title)) AS num_job_titles, AVG(salary) FILTER (WHERE job_title = 'Engineer') AS engineer_avg_salary, COUNT(CASE WHEN job_title = 'Manager' THEN 1 END) AS manager_count FROM scored GROUP BY level ORDER BY manager_count NULLS FIRST
